69	func pushV2RefsWithRecovery(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
70		resultsByRef := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
71		var retryRefs []plumbing.ReferenceName
72	
73		for _, result := range tryPushV2Refs(ctx, target, refs) {
74			if result.err == nil {
75				resultsByRef[result.refName] = result
76				continue
77			}
78			if !errors.Is(result.err, errNonFastForward) {
79				resultsByRef[result.refName] = result
80				continue
81			}
82	
83			shortRef := shortRefName(result.refName)
84			if err := fetchAndMergeRef(ctx, target, result.refName); err != nil {
85				resultsByRef[result.refName] = v2RefPushResult{
86					refName: result.refName,
87					err:     fmt.Errorf("couldn't sync %s: %w", shortRef, err),
88				}
89				continue
90			}
91			retryRefs = append(retryRefs, result.refName)
92		}
93	
94		if len(retryRefs) > 0 {
95			for _, result := range tryPushV2Refs(ctx, target, retryRefs) {
96				if result.err != nil {
97					result.err = fmt.Errorf("failed to push %s after sync: %w", shortRefName(result.refName), result.err)
98				}
99				resultsByRef[result.refName] = result
100			}
101		}
102	
103		results := make([]v2RefPushResult, 0, len(refs))
104		for _, refName := range refs {
105			result, ok := resultsByRef[refName]
106			if !ok {
107				result = v2RefPushResult{
108					refName: refName,
109					err:     errors.New("push result missing"),
110				}
111			}
112			results = append(results, result)
113		}
114		return results
115	}
