382	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
383	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
384	//
385	// For /full/current: if the remote has archived generations not present locally,
386	// another machine rotated. In that case, local data is merged into the latest
387	// archived generation instead of into /full/current (see handleRotationConflict).
388	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
389		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
390		defer cancel()
391	
392		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
393		if err != nil {
394			return fmt.Errorf("resolve fetch target: %w", err)
395		}
396	
397		// Fetch to a temp ref
398		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
399		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
400		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
401	
402		// Recovery flattens fetched trees recursively, so it needs a complete object
403		// graph instead of the normal blobless sync fetch.
404		if output, err := remote.Fetch(ctx, remote.FetchOptions{
405			Remote:    fetchTarget,
406			RefSpecs:  []string{refSpec},
407			NoTags:    true,
408			NoFilter:  true,
409			ExtraArgs: []string{"--no-write-fetch-head"},
410		}); err != nil {
411			return fmt.Errorf("fetch failed: %s", output)
412		}
413	
414		repo, err := OpenRepository(ctx)
415		if err != nil {
416			return fmt.Errorf("failed to open repository: %w", err)
417		}
418		defer func() {
419			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
420		}()
421	
422		// Check for rotation conflict on /full/current
423		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
424			remoteRotationArchives, detectErr := detectRemoteRotationArchives(ctx, target, repo)
425			if detectErr == nil && len(remoteRotationArchives) > 0 {
426				return handleRotationConflict(ctx, target, fetchTarget, repo, refName, tmpRefName, remoteRotationArchives)
427			}
428		}
429	
430		// Standard tree merge (no rotation detected)
431		localRef, err := repo.Reference(refName, true)
432		if err != nil {
433			return fmt.Errorf("failed to get local ref: %w", err)
434		}
435		localCommit, err := repo.CommitObject(localRef.Hash())
436		if err != nil {
437			return fmt.Errorf("failed to get local commit: %w", err)
438		}
439		localTree, err := localCommit.Tree()
440		if err != nil {
441			return fmt.Errorf("failed to get local tree: %w", err)
442		}
443	
444		remoteRef, err := repo.Reference(tmpRefName, true)
445		if err != nil {
446			return fmt.Errorf("failed to get remote ref: %w", err)
447		}
448		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
449		if err != nil {
450			return fmt.Errorf("failed to get remote commit: %w", err)
451		}
452		remoteTree, err := remoteCommit.Tree()
453		if err != nil {
454			return fmt.Errorf("failed to get remote tree: %w", err)
455		}
456	
457		entries := make(map[string]object.TreeEntry)
458		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
459			return fmt.Errorf("failed to flatten local tree: %w", err)
460		}
461		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
462			return fmt.Errorf("failed to flatten remote tree: %w", err)
463		}
464	
465		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
466		if err != nil {
467			return fmt.Errorf("failed to build merged tree: %w", err)
468		}
469	
470		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
471			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
472			"Merge remote "+shortRefName(refName))
473		if err != nil {
474			return fmt.Errorf("failed to create merge commit: %w", err)
475		}
476	
477		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
478		if err := repo.Storer.SetReference(newRef); err != nil {
479			return fmt.Errorf("failed to update ref: %w", err)
480		}
481	
482		return nil
483	}
