485	// detectRemoteRotationArchives discovers archived generation refs on the remote
486	// that are missing locally or whose local ref hash differs from the remote ref
487	// hash. Returns them sorted ascending (oldest first).
488	func detectRemoteRotationArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
489		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
490		defer cancel()
491	
492		output, err := remote.LsRemote(ctx, target, paths.V2FullRefPrefix+"*")
493		if err != nil {
494			return nil, fmt.Errorf("ls-remote failed: %w", err)
495		}
496	
497		var remoteRotationArchives []string
498		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
499			if line == "" {
500				continue
501			}
502			parts := strings.Fields(line)
503			if len(parts) < 2 {
504				continue
505			}
506			refName := parts[1]
507			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
508			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
509				continue
510			}
511			if len(parts[0]) != 40 {
512				return nil, fmt.Errorf("invalid remote archive hash %q for %s", parts[0], refName)
513			}
514			remoteHash := plumbing.NewHash(parts[0])
515			localRef, err := repo.Reference(plumbing.ReferenceName(refName), true)
516			if err != nil || localRef.Hash() != remoteHash {
517				remoteRotationArchives = append(remoteRotationArchives, suffix)
518			}
519		}
520	
521		sort.Strings(remoteRotationArchives)
522		return remoteRotationArchives, nil
523	}
