117	// CatFiles reads specs through git cat-file --batch.
118	func CatFiles(ctx context.Context, opts CatFilesOptions) map[string]CatFileResult {
119		specs := uniqueStrings(opts.Specs)
120		results := make(map[string]CatFileResult, len(specs))
121		if len(specs) == 0 {
122			return results
123		}
124	
125		args := []string{"cat-file"}
126		args = append(args, opts.ExtraArgs...)
127		args = append(args, "--batch")
128		cmd := newCommand(ctx, args...)
129		if opts.Dir != "" {
130			cmd.Dir = opts.Dir
131		}
132		cmd.Stdin = strings.NewReader(strings.Join(specs, "\n") + "\n")
133		disableTerminalPrompt(cmd)
134		var stderr bytes.Buffer
135		cmd.Stderr = &stderr
136	
137		output, err := cmd.Output()
138		if err != nil {
139			wrapped := catFilesError(err, stderr.String())
140			for _, spec := range specs {
141				results[spec] = CatFileResult{Err: wrapped}
142			}
143			return results
144		}
145	
146		reader := bufio.NewReader(bytes.NewReader(output))
147		for i, spec := range specs {
148			result, parseErr := parseBlobBatchEntry(reader)
149			if parseErr != nil {
150				for _, s := range specs[i:] {
151					results[s] = CatFileResult{Err: parseErr}
152				}
153				break
154			}
155			results[spec] = result
156		}
157		return results
158	}
