	// The ancestry probe below only reads commit objects via repo.Log; it never
	// touches blob content. When filtered fetches are available, fetch all
	// candidate archives blobless so we don't pull every shard for every
	// unmatched generation — on repos with many archived generations that
	// transfer dominates pre-push latency. The matched archive needs its blobs
	// for handleRotationConflict's tree flatten + generation.json read, so we
	// top up after the probe identifies the survivor.
	//
	// When filtered fetches aren't enabled (legacy git servers that don't
	// advertise uploadpack.allowFilter, or callers who haven't opted in), keep
	// the pre-optimization behavior: one full-blob fetch up front.
	probeBlobless := settings.IsFilteredFetchesEnabled(ctx)
	if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:    fetchTarget,
		RefSpecs:  refSpecs,
		NoTags:    true,
		NoFilter:  !probeBlobless,
		ExtraArgs: []string{"--no-write-fetch-head"},
	}); fetchErr != nil {
		if repo, openErr := OpenRepository(ctx); openErr == nil {
			cleanupFetchedArchiveTmpRefs(repo, archiveTmpRefs)
		}
		return fetchedRemoteRotationArchive{}, fmt.Errorf("fetch archived generations failed: %s", output)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fetchedRemoteRotationArchive{}, fmt.Errorf("reopen repository after fetching archived generations: %w", err)
	}
	tmpRefsToCleanup := archiveTmpRefs
	defer func() {
		cleanupFetchedArchiveTmpRefs(repo, tmpRefsToCleanup)
	}()

	localCurrentAncestors, ok := currentGenerationAncestors(ctx, repo, localCurrentHash)
	if !ok {
		return fetchedRemoteRotationArchive{}, errors.New("failed to read local /full/current history")
	}
	for _, archive := range archives {
		fetched, err := readFetchedRemoteRotationArchive(repo, archive)
		if err != nil {
			return fetchedRemoteRotationArchive{}, err
		}
		if archiveSharesHistoryWithCurrentGeneration(ctx, repo, localCurrentAncestors, fetched.ref.Hash()) {
			tmpRefsToCleanup = removeRef(tmpRefsToCleanup, fetched.tmpRefName)
			if probeBlobless {
				if err := topUpMatchedArchiveBlobs(ctx, fetchTarget, archive); err != nil {
					return fetchedRemoteRotationArchive{}, fmt.Errorf("top-up blobs for matched archive %s: %w", archive, err)
				}
			}
			return fetched, nil
		}
	}
	return fetchedRemoteRotationArchive{}, errors.New("no remote archive shares history with local /full/current")
}

