// blobAtTopLevel returns the hash of the named entry at the root of refName's
// tree. Used to capture blobs written during rotation (e.g. generation.json)
// rather than shard content the local repo would already have written.
func blobAtTopLevel(t *testing.T, repo *git.Repository, refName plumbing.ReferenceName, name string) plumbing.Hash {
	t.Helper()

	ref, err := repo.Reference(refName, true)
	require.NoError(t, err)
	commit, err := repo.CommitObject(ref.Hash())
	require.NoError(t, err)
	tree, err := commit.Tree()
	require.NoError(t, err)

	for _, entry := range tree.Entries {
		if entry.Name == name {
			return entry.Hash
		}
	}
	t.Fatalf("entry %q not found at top level of %s", name, refName)
	return plumbing.ZeroHash
}

