// --refetch is required because the local temp ref already points at the
// archive's commit after the probe. Without it git's negotiation reports
// "have <commit>" and the server returns nothing, leaving the previously
// filtered blobs missing. --refetch suppresses the haves so the server
// transfers a full pack from scratch.
func topUpMatchedArchiveBlobs(ctx context.Context, fetchTarget, archive string) error {
	archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + archive)
	archiveTmpRef := archiveTmpRefName(archive)
	refSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
	if output, err := remote.Fetch(ctx, remote.FetchOptions{
		Remote:    fetchTarget,
		RefSpecs:  []string{refSpec},
		NoTags:    true,
		NoFilter:  true,
		ExtraArgs: []string{"--no-write-fetch-head", "--refetch"},
	}); err != nil {
		return fmt.Errorf("fetch matched archive blobs: %s", output)
	}
	return nil
}

