// topUpMatchedArchiveBlobs re-fetches the matched archive without the blob
// filter so subsequent tree reads (FlattenTree, updateGenerationTimestamps)
// can resolve blob content. The first probe fetch only brought commits and
// trees; this brings the blobs the probe deliberately skipped.
//
// The local temp ref still points at the archive's commit after the probe,
// which would make a plain "git fetch" negotiate as up-to-date and return an
// empty pack. The repo also may not be configured as a partial clone, so
// --refetch alone isn't reliable. List the blob hashes from the archive's
// tree and fetch them explicitly via fetch-pack, which is the protocol path
// that does not care about ref state.
func topUpMatchedArchiveBlobs(ctx context.Context, fetchTarget string, repo *git.Repository, archiveTmpRef plumbing.ReferenceName) error {
	ref, err := repo.Reference(archiveTmpRef, true)
	if err != nil {
		return fmt.Errorf("read matched archive temp ref: %w", err)
	}
	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return fmt.Errorf("read matched archive commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return fmt.Errorf("read matched archive tree: %w", err)
	}

	missingBlobs, err := missingBlobHashesInTree(repo, tree)
	if err != nil {
		return fmt.Errorf("enumerate missing blobs: %w", err)
	}
	if len(missingBlobs) == 0 {
		return nil
	}

	fetchURL, err := remote.FetchURL(ctx, fetchTarget)
	if err != nil {
		return fmt.Errorf("resolve fetch URL: %w", err)
	}
	if err := remote.FetchBlobs(ctx, fetchURL, missingBlobs); err != nil {
		return fmt.Errorf("fetch matched archive blobs: %w", err)
	}
	return nil
}

// missingBlobHashesInTree walks tree and returns the hashes of all blob
// entries (recursively) that are not present in the local object database.
// Used to drive a targeted fetch-pack when the probe fetch deliberately
// skipped blob content.
func missingBlobHashesInTree(repo *git.Repository, tree *object.Tree) ([]string, error) {
	seen := make(map[plumbing.Hash]struct{})
	var missing []string
	var walk func(*object.Tree) error
	walk = func(t *object.Tree) error {
		for _, entry := range t.Entries {
			if entry.Mode == filemode.Dir {
				sub, err := repo.TreeObject(entry.Hash)
				if err != nil {
					return fmt.Errorf("read subtree %s: %w", entry.Name, err)
				}
				if err := walk(sub); err != nil {
					return err
				}
				continue
			}
			if _, ok := seen[entry.Hash]; ok {
				continue
			}
			seen[entry.Hash] = struct{}{}
			if _, err := repo.BlobObject(entry.Hash); err == nil {
				continue
			} else if !errors.Is(err, plumbing.ErrObjectNotFound) {
				return fmt.Errorf("probe blob %s: %w", entry.Hash, err)
			}
			missing = append(missing, entry.Hash.String())
		}
		return nil
	}
	if err := walk(tree); err != nil {
		return nil, err
	}
	return missing, nil
}

